/* What the hardware does on every memory reference, once a TLB exists. */
uint32_t translate(uint32_t virt)
{
    uint32_t vpn    = virt >> 12;
    uint32_t offset = virt & 0xFFF;

    struct tlb_entry e = tlb_lookup(vpn);   /* every entry compared at once */

    if (e.valid && e.asid == current_asid) {        /* TLB HIT */
        if (!permitted(e.protect))
            raise_exception(PROTECTION_FAULT);
        return (e.pfn << 12) | offset;              /* no page table touched */
    }

    /* TLB MISS: pay for the page table, install the entry, retry */
    uint32_t pte = page_table[vpn];                 /* an extra memory read */
    if (!(pte & PTE_VALID))
        raise_exception(SEGMENTATION_FAULT);
    tlb_insert(vpn, pte >> 12, pte & PTE_PROT_MASK);
    return translate(virt);                         /* second time it hits */
}

/* 12 four-byte ints, the first at virtual address 76, on a machine
   with 16-byte pages.  a[0] sits alone on page 4; a[1..4] on page 5;
   a[5..8] on page 6; a[9..11] on page 7. */
int a[12];                       /* &a[0] == (int *)76 */

int sum = 0;
for (int i = 0; i < 12; i++)
    sum += a[i];                 /* one memory reference per iteration */

/* TLB behaviour, in order:
     a[0]  miss
     a[1]  miss  a[2] hit  a[3] hit  a[4] hit
     a[5]  miss  a[6] hit  a[7] hit  a[8] hit
     a[9]  miss  a[10] hit a[11] hit
   4 misses, 8 hits - a hit rate of two thirds.  The loop asked for
   none of this; the entry simply outlives the access that filled it. */

#define PDE_SHIFT 22             /* top 10 bits: index into the directory */
#define PTE_SHIFT 12             /* next 10 bits: index within one table   */

uint32_t walk(uint32_t virt, uint32_t *dir)
{
    uint32_t pdi = (virt >> PDE_SHIFT) & 0x3FF;
    uint32_t pti = (virt >> PTE_SHIFT) & 0x3FF;
    uint32_t off =  virt & 0xFFF;

    uint32_t pde = dir[pdi];                 /* memory reference 1 */
    if (!(pde & PDE_VALID))
        raise_exception(SEGMENTATION_FAULT); /* a whole 4 MB region is absent */

    uint32_t *table = frame_to_ptr(pde >> 12);
    uint32_t pte = table[pti];               /* memory reference 2 */
    if (!(pte & PTE_VALID))
        raise_exception(SEGMENTATION_FAULT);

    return ((pte >> 12) << 12) | off;        /* the data itself is reference 3 */
}

/* 0x00402ABC -> pdi 1, pti 2, offset 0xABC.
   If that PTE holds frame 0x1F3, the physical address is 0x1F3ABC. */

/* Flush: correct, trivial to build, and it throws everything away. */
void context_switch_flush(struct proc *next)
{
    tlb_flush_all();                  /* next process starts stone cold */
    load_page_table_base(next->ptbr);
    current = next;
}

/* ASIDs: each entry carries the address space it belongs to, so both
   processes' translations coexist and neither is discarded. */
void context_switch_asid(struct proc *next)
{
    write_asid_register(next->asid);  /* lookups now match only these tags */
    load_page_table_base(next->ptbr);
    current = next;
}

/* Neither saves you inside one address space: if the OS unmaps a page
   or downgrades its permissions, it must invalidate that VPN by hand -
   the hardware has no idea the page table underneath it changed. */

